import base64,gzip,json
from pathlib import Path
DATA_B64=''''''
facts=json.loads(gzip.decompress(base64.b64decode(DATA_B64)).decode('utf-8'))
codes={'POL':'राजनीतिक','SOC':'सामाजिक','CUL':'सांस्कृतिक','ECO':'आर्थिक','SCI':'वैज्ञानिक','SPT':'खेलकुद','BOK':'पुस्तक','AWD':'पुरस्कार','ART':'कला','LIT':'साहित्य','MUS':'संगीत','OTH':'अन्य महत्त्वपूर्ण'}
src={'POL':'राष्ट्रपतिको कार्यालय/प्रधानमन्त्री तथा मन्त्रिपरिषद्को कार्यालय/संयुक्त राष्ट्रसंघ/Reuters','SOC':'WHO Nepal','CUL':'UNESCO/UNESCO World Heritage Centre','ECO':'नेपाल अर्थ मन्त्रालय/Reuters','SCI':'NASA/Reuters','SPT':'FIFA/US Open/Wimbledon','BOK':'The Booker Prizes','AWD':'Oscars/Recording Academy (GRAMMY)','ART':'La Biennale di Venezia','LIT':'The Booker Prizes','MUS':'Recording Academy (GRAMMY)','OTH':'United Nations/IAEA'}
out=[]
for code,rows in facts.items():
    cat=codes[code]
    for i,(q,a,ds) in enumerate(rows,1):
        opts=[a]+ds
        for variant in (0,1):
            n=(i-1)*2+variant+1
            if variant==0:
                question=q; typ='fact'
            else:
                question=f'तलका विकल्पमध्ये {cat} क्षेत्रको उक्त समसामयिक तथ्यसँग मिल्ने सही कथन कुन हो?'; typ='correct-statement'
            target=(n-1)%4
            ordered=opts[:]
            ans=ordered.pop(0)
            ordered.insert(target,ans)
            out.append({'id':f'bo-1.8-{code}-{n:02d}','unit':'1.8','category':cat,'level':'I' if n<=10 else 'II','type':typ,'question':question,'options':ordered,'correct':target,'solution':f'सही उत्तर: {"ABCD"[target]}। {a}','source':src[code],'asOf':'2026-09-12'})
assert len(out)==240
Path('exam-question-seed/generated-branch-officer-1.8.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('generated',len(out))
